// generar_271_dias_con_paseo_consistente.js
// CHIQUI Entre Señales — "Días con paseo" consistente con la racha
//
// PROBLEMA: Análisis mostraba "Días con paseo: 20 de 24" habiendo
// registrado paseo los 24 días, mientras la racha sí contaba todos.
// Dos reglas distintas para lo mismo:
//   · La RACHA cuenta un día si tiene paseo distinto de "No paseó".
//   · "Días con paseo" exigía además que los MINUTOS fueran > 0.
//
// La diferencia aparece con la opción "⏱️ Registrar tiempo exacto":
// sus selectores parten en 0h 0min y solo guardan al tocarlos, así
// que si se elige esa opción sin marcar la duración, el registro
// queda con paseo_minutos_exactos en null. Ese día tuvo paseo (cuenta
// en la racha) pero calcula 0 minutos, y el contador lo descartaba.
//
// CAMBIOS:
//
// 1) "Días con paseo" ahora usa el MISMO criterio que la racha: el
//    paseo ocurrió, aunque no sepamos cuánto duró.
//
// 2) "Promedio por salida" se calcula solo sobre los días con duración
//    conocida. Dividir por días sin duración hundiría el promedio con
//    ceros que no son ceros reales, sino datos faltantes.
//
// 3) Aviso honesto en el detalle del mes cuando hay salidas sin
//    duración: "Hay 3 días con paseo sin duración registrada, así que
//    no suman minutos al total. Puedes completarla editando esos
//    días." Sin eso, el total de horas se ve bajo sin explicación.
//
// 4) PREVENCIÓN en el registro diario: al elegir "tiempo exacto" sin
//    marcar la duración aparece un aviso naranjo — "Elige la duración
//    para que este paseo sume al total del mes. Si no la sabes, puedes
//    usar uno de los rangos de arriba." Antes el dato se perdía en
//    silencio.
//
// NOTA: los días que ya quedaron sin duración siguen sin minutos hasta
// que los edites; el script no inventa duraciones retroactivas.
//
// No hay SQL.
//
// Uso:
//   node generar_271_dias_con_paseo_consistente.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/analisis/page.tsx",
    base64: ""
  },
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
